{
  "source": "inputs/story-input.json#characters",
  "status": "planning_only",
  "characters": {
    "宋棠": {
      "identity": "社区旧车站照片展的年轻整理者",
      "want": "认全照片中的人，让观众愿意停下来看看",
      "concern": "照抄名单遗漏真实的人，或凭猜测误导观众",
      "history": "刚接手整理，齐叔是熟悉旧站的老志愿者",
      "voice": "问具体问题，有新依据时会改口，不把推理当训话"
    },
    "齐叔": {
      "identity": "退休的旧站职工、展览志愿者",
      "want": "把同伴的事讲准确",
      "concern": "记忆模糊说错人，也怕缺名被直接说成恶意抹去",
      "history": "参加过照片里的搬书，记得四位同事，不知道临时帮忙者全名",
      "voice": "习惯用旧称呼，证据摆出来会认记混"
    },
    "程雪": {
      "identity": "匿名寄照片者，林琴的女儿",
      "want": "母亲在照片下有自己的名字",
      "concern": "被说成替母亲讨功，或母亲不愿露面",
      "history": "家里保有同日另一照片和母亲的便条",
      "voice": "不肯夸大功劳，但愿意出示具体材料"
    },
    "林琴": {
      "identity": "照片里的第五人，当年的邮递员",
      "want": "名字写对，也别写成没做过的英雄",
      "concern": "临时搭手被展览渲染成传奇",
      "history": "路过旧站时帮忙搬被雨水威胁的书，借过站员外套，不是车站职工",
      "voice": "朴实具体，会纠正过分赞美"
    }
  },
  "narrative_pov": "第三人称贴近宋棠，不进入他人内心",
  "provided_approved_samples": []
}

{
  "source": "inputs/story-input.json",
  "decision": "仅在已批准三章边界内具体化表现",
  "chapters": [
    {
      "chapter": 1,
      "problem": "查人数易写成名册核验步骤",
      "chosen_interaction": "齐叔珍惜老同伴的合影，但怕自己说错；宋棠既不顺从猜测，也不把缺名指成恶意。留空行是她当场选择。",
      "rejected_alternative": "指控旧站蓄意裁人，超越题材边界。"
    },
    {
      "chapter": 2,
      "problem": "女儿提供资料易成为单向信息倾倒",
      "chosen_interaction": "程雪先看见空行才愿意取出资料；宋棠想及时补名，程雪把母亲意愿放在前面。两人用另一照片推翻外套职业判断。",
      "rejected_alternative": "追加取证阻碍或调查第三人，未获授权。"
    },
    {
      "chapter": 3,
      "problem": "核对事实易重复前章清点",
      "chosen_interaction": "林琴和齐叔先各自认位置，借衣与搬书由记忆差异接话对上；她主动限制展牌的夸赞，宋棠保留准确的普通搭手。",
      "rejected_alternative": "再加隐瞒身份或大恩怨以制造高潮。"
    }
  ]
}
